with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'مختبرات التحليل ودراسات الحالات الجوية التطبيقية','دراسات تطبيقية لحالات المنخفضات والأخاديد والثلوج والحر والغبار والنسيم والضباب والعواصف والسيول والجفاف.',27,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'دراسات الحالات السينوبتيكية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'دراسات الحالات الجوية المحلية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'دراسات الحالات الهيدرولوجية',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('case-study-mediterranean-frontal-rain','دراسة حالة: منخفض متوسطي وهطول جبهي','تحليل متكامل لمسار منخفض وجبهة باردة وتوزيع الهطول.','{"blocks":[{"type":"text","text":"تبدأ دراسة الحالة بتحديد وقت بداية المنخفض وموقعه ومساره خلال فترة التحليل."},{"type":"text","text":"تجمع خرائط الضغط السطحي وخرائط 850 و700 و500 hPa وصور الأقمار والرادار والمحطات."},{"type":"text","text":"يحدد مركز المنخفض وتدرج الضغط واتجاه الرياح وموقع الجبهات في كل وقت مرجعي."},{"type":"text","text":"تفحص خريطة 850 hPa لتحديد انتقال الهواء الدافئ والبارد والرطوبة في الطبقات السفلى."},{"type":"text","text":"تفحص خرائط 700 hPa والحركة الرأسية لتحديد مناطق الرطوبة والرفع المحتملة."},{"type":"text","text":"تستخدم خريطة 500 hPa لتحديد علاقة الأخدود العلوي بالمنخفض السطحي وتوقيت التفاعل."},{"type":"text","text":"تقارن صور الرادار المتتابعة بتوقعات النماذج لتحديد نطاق الهطول وتطوره."},{"type":"text","text":"تراجع كميات المطر في المحطات مع مراعاة اختلاف فترة التجميع والارتفاع والتعرض."},{"type":"text","text":"يفصل التقييم بين خطأ توقيت الجبهة وخطأ موقع نطاق المطر وخطأ الكمية."},{"type":"text","text":"تسجل العوامل التي حسنت أو أضعفت التوقع، مثل سرعة المنخفض أو عمق الرطوبة أو تأثير التضاريس."},{"type":"text","text":"مثال: قد يتوقع النموذج مرور الجبهة في موعد صحيح لكنه يبالغ في المطر الداخلي بسبب تمثيل غير دقيق للرطوبة والتضاريس."},{"type":"callout","text":"خلاصة: دراسة المنخفض الجبهي تجمع التحليل الرأسي والرصد والتقييم الكمي بعد الحدث."}]}',1960,60,'["بناء التسلسل الزمني للحالة","تحليل الجبهة والطبقات العليا","مقارنة المطر المتوقع بالمرصود"]','دراسات الحالات السينوبتيكية'),
('case-study-red-sea-trough-instability','دراسة حالة: أخدود البحر الأحمر وعدم الاستقرار','تشخيص تفاعل الأخدود السطحي مع الهواء البارد العلوي والرطوبة.','{"blocks":[{"type":"text","text":"يحدد التحليل موقع محور أخدود البحر الأحمر وامتداده واتجاه الرياح حوله خلال الحالة."},{"type":"text","text":"تجمع خرائط الضغط السطحي و850 و700 و500 hPa وملفات السبر والرطوبة وصور الأقمار."},{"type":"text","text":"يفحص توزيع الحرارة والرطوبة في الطبقات السفلى لتحديد مصدر الهواء وعمق الرطوبة."},{"type":"text","text":"تراجع درجات الحرارة في الطبقات العليا لتقييم وجود هواء بارد يزيد التدرج الحراري الرأسي."},{"type":"text","text":"تحسب مؤشرات الاستقرار مثل CAPE وCIN عند توافر ملفات سبر مناسبة، مع تفسيرها في سياق البيئة."},{"type":"text","text":"تحدد مناطق التقارب السطحي والرفع التضاريسي والتفاعل مع الأخدود العلوي."},{"type":"text","text":"تستخدم صور الرادار والبرق لتتبع بدء الخلايا الحملية ونموها وتجددها."},{"type":"text","text":"تراجع حركة الخلايا واتجاهها وسرعتها ومدى استمرارها فوق الأحواض."},{"type":"text","text":"تقارن التوقعات الاحتمالية بمواقع الهطول الفعلية بدلاً من الاعتماد على قيمة نموذجية واحدة."},{"type":"text","text":"تحدد القيود مثل ضعف الرصد أو عدم تمثيل الخلايا الصغيرة أو تغيرها السريع."},{"type":"text","text":"مثال: أخدود سطحي دون رطوبة كافية قد يبقى جافاً، بينما يؤدي تفاعله مع هواء بارد ورطوبة ورفع إلى اضطرابات حملية."},{"type":"callout","text":"خلاصة: لا تكفي تسمية النظام؛ فالتشخيص يعتمد على البنية الحرارية والرطوبة والرفع والرصد."}]}',1970,60,'["تحليل بنية الأخدود","تقييم عدم الاستقرار والرطوبة","تحديد مناطق الرفع"]','دراسات الحالات السينوبتيكية'),
('case-study-mountain-snow-forecast','دراسة حالة: توقع الثلوج على المرتفعات','تحليل الملف الحراري ومستوى التجمد وتراكم الثلوج والتحقق الأرضي.','{"blocks":[{"type":"text","text":"تحدد دراسة الحالة نطاق الارتفاعات والمواقع الجبلية وفترة الهطول المراد تقييمها."},{"type":"text","text":"تجمع ملفات السبر وخرائط الحرارة عند 850 و700 hPa وبيانات المحطات الجبلية."},{"type":"text","text":"يحدد مستوى الصفر الحراري ومستوى البصيلة الرطبة وعمق الطبقات الدافئة والباردة."},{"type":"text","text":"تراجع شدة الهطول وتأثير التبريد التبخري والذوبان على حدود تساقط الثلج."},{"type":"text","text":"تقارن درجات الحرارة على السفوح والقمم والوديان مع مراعاة اختلاف التعرض والارتفاع."},{"type":"text","text":"تستخدم توقعات النماذج لتقدير توقيت بداية الهطول ونهايته وتغير مستوى الثلج."},{"type":"text","text":"يجب التمييز بين مستوى التجمد ومستوى تساقط الثلج الفعلي وارتفاع التراكم."},{"type":"text","text":"تجمع تقارير الثلج الأرضية وعمق الثلج ومكافئ الماء عند توافرها."},{"type":"text","text":"تراجع أثر الرياح والانجراف والذوبان على التوزيع المكاني للغطاء الثلجي."},{"type":"text","text":"يحسب خطأ التوقع في توقيت البداية والارتفاع والكمية كل على حدة."},{"type":"text","text":"مثال: قد يتنبأ النموذج بمستوى تجمد منخفض، لكن هطولاً ضعيفاً وهواءً جافاً قد يرفع مستوى الثلج الفعلي."},{"type":"callout","text":"خلاصة: توقع الثلج يحتاج ملفاً حرارياً ورطوبياً كاملاً وتحققاً ميدانياً متدرج الارتفاع."}]}',1980,60,'["تحليل الملف الحراري الرأسي","تقدير مستوى الثلج","مراجعة التراكمات المرصودة"]','دراسات الحالات الجوية المحلية'),
('case-study-heatwave-analysis','دراسة حالة: تحليل موجة حر ممتدة','تتبع المرتفع الجوي والهبوط وميزانية الطاقة والانحرافات الحرارية.','{"blocks":[{"type":"text","text":"تحدد موجة الحر باستخدام تعريف محلي واضح للعتبة والمدة والفترة المناخية المرجعية."},{"type":"text","text":"تجمع درجات الحرارة اليومية والدنيا والقصوى وبيانات الرطوبة والرياح والغطاء السحابي."},{"type":"text","text":"تفحص خرائط الضغط والارتفاعات العليا لتحديد موقع المرتفع الجوي واستمراره وحركته."},{"type":"text","text":"تراجع الهبوط الجوي والسماء الصافية والرياح والحرارة السطحية لتفسير استمرار التسخين."},{"type":"text","text":"تقارن درجات الحرارة بالمعدلات المناخية وتحدد مقدار الشذوذ ومدته وتوزيعه المكاني."},{"type":"text","text":"تستخدم بيانات طبقة الخلط والحرارة الليلية لتقييم غياب التبريد الليلي أو ضعفه."},{"type":"text","text":"تراجع أثر الجزر الحرارية الحضرية والارتفاع والبعد عن الساحل في الفروق المحلية."},{"type":"text","text":"تقارن توقعات النماذج والمنتجات التجميعية مع المشاهدات على مدى أيام الحالة."},{"type":"text","text":"يفصل التقييم بين توقع بداية الموجة وتوقع ذروتها ومدتها ودرجات الحرارة الدنيا."},{"type":"text","text":"توثق مصادر البيانات وفترة المرجع وحدود المحطات والمنتجات المستخدمة."},{"type":"text","text":"مثال: قد تكون الذروة النهارية متوقعة جيداً بينما تقل دقة الحرارة الدنيا بسبب تمثيل السحب والرياح الليلية."},{"type":"callout","text":"خلاصة: دراسة موجة الحر تربط الدوران واسع النطاق بالطاقة السطحية والخصائص المحلية."}]}',1990,60,'["تحديد بداية الموجة ونهايتها","تحليل أسباب استمرار الحرارة","تقييم الشذوذ الحراري"]','دراسات الحالات الجوية المحلية'),
('case-study-dust-outbreak-tracking','دراسة حالة: تتبع عاصفة غبارية إقليمية','تحليل مصدر الغبار ومساره وارتفاعه وتوزيعه السطحي.','{"blocks":[{"type":"text","text":"تبدأ الدراسة بتحديد توقيت ظهور الغبار ومناطق التأثير واتجاه الحركة."},{"type":"text","text":"تراجع خرائط الضغط والرياح السطحية والعليا لتحديد الأنظمة التي ولدت الرياح الناقلة."},{"type":"text","text":"تفحص صور الأقمار المرئية ومنتجات الهباء لتحديد مسار الغبار وامتداده الرأسي التقريبي."},{"type":"text","text":"تستخدم محطات الرؤية وجودة الهواء وPM10 وPM2.5 لتقييم الأثر قرب السطح."},{"type":"text","text":"تميز بين الغبار المرتفع والغبار الملامس للسطح لأن الأثر على الرؤية والصحة قد يختلف."},{"type":"text","text":"تراجع رطوبة التربة والغطاء الأرضي ومصادر الغبار المحتملة في مناطق المنشأ."},{"type":"text","text":"تتابع الجبهات وحدود الهبات التي قد تثير موجات غبار جديدة أثناء انتقال الحالة."},{"type":"text","text":"تقارن توقعات الغبار بوقت الوصول ومناطق التركيز الفعلي وتغير الرؤية."},{"type":"text","text":"تراجع أثر السحب والأسطح الساطعة على جودة الاسترجاع الفضائي."},{"type":"text","text":"تحدد أوجه عدم اليقين في تحديد المصدر والارتفاع والتركيز السطحي."},{"type":"text","text":"مثال: قد تظهر صورة القمر سحابة غبار واسعة، بينما تتركز أعلى تراكيز الجسيمات السطحية في شريط أضيق بحسب الخلط الرأسي."},{"type":"callout","text":"خلاصة: تتبع الغبار يحتاج دمج بيانات الأقمار والرياح والمحطات وجودة الهواء."}]}',2000,60,'["تحديد مصدر الغبار","تتبع النقل الإقليمي","مقارنة الاستشعار بالرصد الأرضي"]','دراسات الحالات الجوية المحلية'),
('case-study-sea-breeze-and-coastal-convergence','دراسة حالة: نسيم البحر والتقارب الساحلي','تحليل التباين الحراري الساحلي وتطور جبهة نسيم البحر والسحب المحلية.','{"blocks":[{"type":"text","text":"يتطور نسيم البحر غالباً نهاراً نتيجة اختلاف سرعة تسخين اليابسة والبحر."},{"type":"text","text":"ينشأ تدرج حراري وضغطي محلي يدعم تدفق هواء أبرد نسبياً من البحر نحو اليابسة."},{"type":"text","text":"قد تتقدم جبهة نسيم البحر إلى الداخل وتلتقي برياح محلية أو تدفقات أخرى."},{"type":"text","text":"يساعد تباين الحرارة بين الساحل والداخل وخرائط الرياح السطحية على تحديد وقت بداية النسيم."},{"type":"text","text":"تؤثر سرعة الرياح العامة واتجاهها في قوة النسيم وعمق تقدمه نحو الداخل."},{"type":"text","text":"قد ينتج التقارب على جبهة النسيم حركة صاعدة وسحباً ركامية إذا توافرت الرطوبة وعدم الاستقرار."},{"type":"text","text":"تستخدم المحطات الساحلية والداخلية لمتابعة تغير الحرارة والرطوبة والرياح والضغط."},{"type":"text","text":"تساعد صور الرادار والأقمار في رصد تطور السحب على طول نطاق التقارب."},{"type":"text","text":"قد يتأخر نسيم البحر أو يضعف عندما تكون الرياح العامة قوية ومعاكسة أو عندما يكون التدرج الحراري ضعيفاً."},{"type":"text","text":"تراجع الحالة عبر عدة أيام لتحديد أثر الموسم والتضاريس والظروف الخلفية."},{"type":"text","text":"مثال: قد يتشكل خط سحب على جبهة النسيم فوق الداخل رغم صفاء السماء على الساحل."},{"type":"callout","text":"خلاصة: نسيم البحر ظاهرة محلية ديناميكية تتأثر بالتسخين والرياح العامة والتضاريس."}]}',2010,60,'["تحديد دورة نسيم البحر","تحليل التقارب الساحلي","تقييم أثر الرياح العامة"]','دراسات الحالات الجوية المحلية'),
('case-study-coastal-fog-event','دراسة حالة: تشكل الضباب الساحلي وتبدده','تحليل انتقال الهواء فوق البحر وتغير الحرارة والرطوبة والرؤية.','{"blocks":[{"type":"text","text":"تحدد الحالة من خلال تقارير الرؤية وقاعدة السحب ودرجة الحرارة ونقطة الندى في المحطات الساحلية."},{"type":"text","text":"يفحص اتجاه الرياح لمعرفة ما إذا كان الهواء ينتقل من سطح بحري أبرد أو أدفأ نسبياً."},{"type":"text","text":"تراجع حرارة سطح البحر والهواء وفرق الحرارة والرطوبة لتقييم قابلية الوصول إلى الإشباع."},{"type":"text","text":"تستخدم صور الأقمار والليدار ومقاييس الرؤية لتحديد امتداد الضباب وعمقه عند توافرها."},{"type":"text","text":"يجب التمييز بين الضباب الإشعاعي والانتقالي والبحري وفق آلية التشكل لا الموقع وحده."},{"type":"text","text":"تؤثر سرعة الرياح في عمق طبقة الضباب واستمرارها أو تشتتها."},{"type":"text","text":"قد يؤدي التسخين الشمسي بعد الشروق إلى رفع قاعدة الضباب أو تبديده، لكن ذلك يعتمد على الاستقرار والرطوبة."},{"type":"text","text":"تراجع التقارير المتتابعة لتحديد بداية انخفاض الرؤية ومدته ونهاية الحالة."},{"type":"text","text":"تقارن توقعات الضباب بمواقع المحطات وبالفترة الزمنية الفعلية لتقييم الأداء."},{"type":"text","text":"توثق العوامل التي أخرت التبدد مثل السحب المنخفضة أو استمرار تدفق هواء رطب."},{"type":"text","text":"مثال: قد يستمر ضباب ساحلي رغم ارتفاع الحرارة قليلاً إذا استمر تدفق الهواء الرطب فوق مياه باردة."},{"type":"callout","text":"خلاصة: دراسة الضباب الساحلي تحتاج رصداً متزامناً للهواء والبحر والرؤية والرياح."}]}',2020,60,'["تمييز نوع الضباب","تحليل شروط التشكل","تقدير زمن التبدد"]','دراسات الحالات الجوية المحلية'),
('case-study-convective-storm-nowcasting','دراسة حالة: التنبؤ الآني بعاصفة رعدية','دمج الرادار والبرق والأقمار والسبر لتتبع تطور خلية حملية.','{"blocks":[{"type":"text","text":"تبدأ الدراسة بتحديد البيئة السابقة للعاصفة من السبر والرطوبة والاستقرار والقص."},{"type":"text","text":"تراجع خرائط التقارب والحرارة والرفع لتحديد آليات بدء الحمل."},{"type":"text","text":"تستخدم صور الرادار المتتابعة لتحديد نشوء الخلية ونموها وحركتها وشدتها النسبية."},{"type":"text","text":"تستخدم بيانات البرق لمتابعة النشاط الكهربائي وتغيره الزمني."},{"type":"text","text":"تستخدم صور الأقمار لتتبع نمو قمم السحب وتطور درجة حرارتها."},{"type":"text","text":"يقدر اتجاه الحركة وسرعتها من مسارات الخلايا مع التمييز بين الحركة والتجدد والنمو."},{"type":"text","text":"تحدد حدود الهبات والتقارب التي قد تؤدي إلى تشكل خلايا جديدة."},{"type":"text","text":"تراجع مخرجات النماذج قصيرة المدى ومقارنتها بالرصد في كل تحديث."},{"type":"text","text":"يحدد نطاق التأثير المتوقع مع بيان عدم اليقين في الموقع والتوقيت والشدة."},{"type":"text","text":"تقارن التوقعات الآنية بما تحقق باستخدام وقت إصدار المنتج ومهلة التنبؤ الصحيحة."},{"type":"text","text":"مثال: قد يتوقع الاستقراء انتقال الخلية إلى الشرق، لكن نشوء خلية جديدة جنوبها يغير نطاق التأثير."},{"type":"callout","text":"خلاصة: التنبؤ الآني يتطلب مراقبة متواصلة وتحديث السيناريو مع كل دليل جديد."}]}',2030,60,'["تشخيص بيئة العاصفة","تتبع الخلية زمنياً","تقييم مهارة التنبؤ الآني"]','دراسات الحالات الجوية المحلية'),
('case-study-flash-flood-catchment','دراسة حالة: استجابة حوض صغير لهطول غزير','دمج بيانات المطر والتضاريس والتربة والتصريف لتحليل السيول.','{"blocks":[{"type":"text","text":"تحدد حدود الحوض ومساحته وشكله وانحداره وشبكة التصريف قبل تحليل الحدث."},{"type":"text","text":"تجمع بيانات المطر من المحطات والرادار مع مطابقة فترات القياس والتراكم."},{"type":"text","text":"تراجع رطوبة التربة السابقة وخصائص النفاذية والغطاء الأرضي والتوسع العمراني."},{"type":"text","text":"يحدد توقيت بدء الهطول وشدته القصوى ومدته والتوزيع المكاني داخل الحوض."},{"type":"text","text":"تستخدم بيانات المنسوب والتصريف لبناء الهيدروغراف وتحديد زمن الذروة ومقدارها."},{"type":"text","text":"تراجع أثر التخزين السطحي والتسرب والتوجيه عبر المجاري والمنشآت."},{"type":"text","text":"تقارن التوقعات المطرية بالتوقعات الهيدرولوجية لتحديد مصدر الخطأ أو عدم اليقين."},{"type":"text","text":"يجب التمييز بين التنبؤ بكمية المطر والتنبؤ بعمق المياه أو توقيت الفيضان."},{"type":"text","text":"تراجع التقارير الميدانية وحدود الفيضانات المرصودة للتحقق من النموذج."},{"type":"text","text":"تحدد فجوات الرصد أو ضعف تمثيل الحوض التي أثرت في جودة التوقع."},{"type":"text","text":"مثال: حوض صغير مشبع قد يستجيب بسرعة لهطول قصير، بينما حوض أكبر قد يظهر ذروة متأخرة وتوزيعاً مختلفاً."},{"type":"callout","text":"خلاصة: تحليل السيول يحتاج نموذجاً مترابطاً للطقس والحوض والمجرى والبيانات المرصودة."}]}',2040,60,'["توصيف خصائص الحوض","تحليل المطر والجريان","تقييم زمن الاستجابة"]','دراسات الحالات الهيدرولوجية'),
('case-study-drought-monitoring-season','دراسة حالة: متابعة موسم جفاف وتقييم شدته','تحليل الهطول والتبخر-النتح ورطوبة التربة والتدفق عبر الموسم.','{"blocks":[{"type":"text","text":"تبدأ الدراسة بتحديد تعريف الجفاف ونوعه والفترة المرجعية المناسبة للمنطقة."},{"type":"text","text":"تجمع سجلات الهطول الشهرية والحرارة وET0 ورطوبة التربة والتدفق النهري عند توافرها."},{"type":"text","text":"يحسب شذوذ الهطول ومؤشرات SPI على مدد زمنية مناسبة للسؤال."},{"type":"text","text":"يمكن استخدام SPEI لتضمين الطلب التبخري المرجعي في تقييم الجفاف المناخي."},{"type":"text","text":"تراجع رطوبة التربة لتقييم الجفاف الزراعي، مع مراعاة نوع التربة والعمق والمحصول."},{"type":"text","text":"تراجع مستويات الأنهار والخزانات والمياه الجوفية لتقييم الجفاف الهيدرولوجي."},{"type":"text","text":"تحدد بداية الجفاف وذروته ومدته ومناطق امتداده، وقد تختلف هذه المراحل بين المؤشرات."},{"type":"text","text":"تستخدم صور الأقمار لمراقبة الغطاء النباتي وبعض مؤشرات الرطوبة السطحية مع إدراك حدودها."},{"type":"text","text":"تربط النتائج ببيانات استخدام المياه والطلب الزراعي وإدارة الخزانات عند دراسة الأثر."},{"type":"text","text":"توضح الدراسة الفروق بين النقص المطري المؤقت واستمرار أثره في المخزون المائي."},{"type":"text","text":"مثال: تحسن المطر في شهر واحد قد يرفع SPI قصير الأمد دون أن ينهي الجفاف الهيدرولوجي المتراكم."},{"type":"callout","text":"خلاصة: تقييم الجفاف عملية متعددة المؤشرات والمقاييس الزمنية والقطاعات."}]}',2050,60,'["تحديد فترة الجفاف","اختيار مؤشرات مناسبة","تقييم الأثر الهيدرولوجي"]','دراسات الحالات الهيدرولوجية'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'دراسات الحالات السينوبتيكية' then u1.id when 'دراسات الحالات الجوية المحلية' then u2.id when 'دراسات الحالات الهيدرولوجية' then u3.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'مختبرات التحليل ودراسات الحالات الجوية التطبيقية',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;